package vn.xuannhashop.business.finance.application;
import java.math.BigDecimal;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import vn.xuannhashop.business.shared.security.ActorContext;
import vn.xuannhashop.business.shared.*;
import vn.xuannhashop.business.shared.audit.ActivityService;
@Service
public class FinanceService implements FinanceApplication {
    private final FinanceRepository r;private final ActorContext actor;private final ActivityService audit;private final Commands commands;
    public FinanceService(FinanceRepository r,ActorContext actor,ActivityService audit,Commands commands){this.r=r;this.actor=actor;this.audit=audit;this.commands=commands;}
    public Balance balances(UUID order){return r.balances(order);}
    public List<Map<String,Object>> ledger(){actor.require("OWNER","ACCOUNTANT");return r.ledger();}
    public List<Map<String,Object>> approvals(){actor.require("OWNER","ACCOUNTANT");return r.approvals();}
    @Transactional public UUID receive(UUID order,String kind,BigDecimal amount,String note,String key){actor.require("OWNER","ACCOUNTANT");Checks.money(amount);if(kind==null||!Set.of("DEPOSIT_IN","RENTAL_IN","CHARGE_IN").contains(kind))throw DomainException.bad("Loại khoản thu không hợp lệ.");Checks.text(note,500,"Căn cứ thu tiền");return commands.once(key,"RECEIVE:"+order+":"+kind+":"+amount+":"+note,()->{var o=r.lockOrder(order);if(o==null)throw DomainException.missing();var b=balances(order);var remaining=kind.equals("DEPOSIT_IN")?((BigDecimal)o.get("deposit_required")).subtract(b.depositHeld()):kind.equals("CHARGE_IN")?b.chargesDue().subtract(b.chargesPaid()):((BigDecimal)o.get("rental_total")).subtract(b.rentalPaid());if(amount.compareTo(remaining)>0)throw DomainException.bad("Khoản thu vượt số tiền còn phải nhận theo thỏa thuận.");var id=UUID.randomUUID();r.record(id,order,null,kind,amount,key,actor.username(),note,null);audit.record("MONEY_RECEIVED",order,kind+" "+amount);audit.notifyOrder(order,"PAYMENT_RECORDED",kind);return id;});}
    @Transactional public UUID requestRefund(UUID order,BigDecimal amount,String reason,String key){actor.require("OWNER","ACCOUNTANT");Checks.money(amount);Checks.text(reason,500,"Lý do hoàn cọc");return commands.once(key,"REFUND_REQUEST:"+order+":"+amount+":"+reason,()->{var o=r.lockOrder(order);if(o==null)throw DomainException.missing();eligible(o,order);if(amount.compareTo(balances(order).depositHeld().subtract(r.pendingRefunds(order)))>0)throw DomainException.bad("Khoản hoàn vượt cọc còn giữ sau các yêu cầu đang chờ duyệt.");var id=UUID.randomUUID();r.request(id,order,amount,actor.username(),reason);audit.record("REFUND_REQUESTED",order,"amount="+amount);return id;});}
    private void eligible(Map<String,Object> o,UUID order){if(balances(order).chargesPaid().compareTo(balances(order).chargesDue())<0)throw DomainException.conflict("Cần đối chiếu và thu đủ khoản bồi thường đã duyệt trước khi hoàn cọc.");if(!Set.of("CANCELLED","EXPIRED","AWAIT_SETTLEMENT").contains(o.get("status")))throw DomainException.conflict("Chỉ hoàn cọc cho đơn hủy, hết hạn hoặc đã trả đủ thiết bị.");if(o.get("status").equals("AWAIT_SETTLEMENT")&&!r.inspected(order))throw DomainException.conflict("Cần hoàn tất kiểm tra thiết bị đã trả trước khi hoàn cọc.");}
    @Transactional public void decide(UUID approval,boolean approved,String key){actor.require("OWNER","ACCOUNTANT");commands.once(key,"REFUND_DECIDE:"+approval+":"+approved,()->{var a=r.lockApproval(approval);if(a==null)throw DomainException.missing();if(!a.get("status").equals("PENDING"))throw DomainException.conflict("Yêu cầu đã được xử lý.");if(a.get("requester").equals(actor.username()))throw DomainException.forbidden();UUID order=(UUID)a.get("target_id");var o=r.lockOrder(order);if(o==null)throw DomainException.missing();if(approved){eligible(o,order);var amount=(BigDecimal)a.get("amount");if(amount.compareTo(balances(order).depositHeld())>0)throw DomainException.conflict("Số dư cọc đã thay đổi.");r.record(UUID.randomUUID(),order,null,"DEPOSIT_REFUND",amount,"refund:"+approval,actor.username(),(String)a.get("reason"),approval);}r.decide(approval,approved,actor.username());audit.record(approved?"REFUND_APPROVED":"REFUND_REJECTED",order,"approval="+approval);return approval;});}
    @Transactional public void addCharge(UUID order,UUID incident,BigDecimal amount,String reason){actor.require("OWNER","ACCOUNTANT");r.addCharge(order,incident,amount,reason,actor.username());audit.record("CHARGE_APPROVED",order,"incident="+incident+" / "+amount);}
    @Transactional public void payPayroll(UUID payroll,BigDecimal amount,String key){actor.require("OWNER","ACCOUNTANT");Checks.money(amount);r.record(UUID.randomUUID(),null,payroll,"PAYROLL_OUT",amount,key,actor.username(),"Chi bảng lương đã duyệt",null);audit.record("PAYROLL_PAID",payroll,"amount="+amount);}
    @Transactional public void payAdvance(UUID adjustment,BigDecimal amount,String note,String key){actor.require("OWNER","ACCOUNTANT");Checks.money(amount);r.record(UUID.randomUUID(),null,null,"PAYROLL_ADVANCE_OUT",amount,key,actor.username(),note,null);audit.record("PAYROLL_ADVANCE_PAID",adjustment,"amount="+amount);}
}
